import type { Metadata } from 'next'
import HomeView, { homeMetadata } from './_home/HomeView'

/*
 * `/` with no view parameter: a STATIC page, regenerated by the hourly fetch
 * revalidation and the `site:<slug>` webhook tag like every other one.
 *
 * It must never read `searchParams` — that alone made the home page dynamic
 * (SEO audit O4). `/?page=` and `/?country=` are rewritten by the proxy to
 * app/home-view/[country]/[page] instead; see lib/seo/homeView.ts.
 */
export function generateMetadata(): Metadata {
  return homeMetadata(1)
}

export default function HomePage() {
  return <HomeView page={1} />
}
